import type { CompanionSpecies, SupportedLanguage } from '../../domain/entities';
import type { SeedResult } from '../seed';

/**
 * Synthetic demo personas (schema: core.schema.json). Files are generated by the team
 * (5 personas × 90 days). The app NEVER reads ground_truth/.
 *
 * To add one: drop `<id>.json` in this folder and register it in PERSONA_FILES below.
 */
export interface PersonaMeta {
  id: string;
  displayName: string;
  story?: string;
  language?: SupportedLanguage;
  companion?: { species: CompanionSpecies; name: string };
  bipolarFlag?: boolean;
  trustedContact?: { name: string; phone: string };
}

export interface Persona extends SeedResult {
  persona: PersonaMeta;
}

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** Minimal runtime validation so a malformed file fails loudly in dev instead of breaking the demo. */
export function parsePersona(raw: unknown): Persona {
  const p = raw as Partial<Persona>;
  if (!p || typeof p !== 'object') throw new Error('Persona: not an object');
  if (!p.persona?.id || !p.persona.displayName) throw new Error('Persona: missing persona.id / displayName');
  if (!Array.isArray(p.checkIns) || !Array.isArray(p.sensors) || !Array.isArray(p.feedback)) {
    throw new Error(`Persona ${p.persona.id}: checkIns, sensors and feedback must be arrays`);
  }
  for (const c of p.checkIns) {
    if (!DATE.test(c.date) || !Number.isInteger(c.mood) || c.mood < 1 || c.mood > 5 || typeof c.safetyConcern !== 'boolean') {
      throw new Error(`Persona ${p.persona.id}: invalid check-in ${c.id}`);
    }
  }
  for (const s of p.sensors) {
    if (!DATE.test(s.date)) throw new Error(`Persona ${p.persona.id}: invalid sensor date ${s.date}`);
  }
  return p as Persona;
}

/** Registered persona files (static requires so Metro bundles them). */
const PERSONA_FILES: unknown[] = [
  // require('./stays-well.json'),
  // require('./aino.json'),
];

export const PERSONAS: Persona[] = PERSONA_FILES.map(parsePersona);
